-- Abingdon Stainfree carpets: every range on Abingdon's Stainfree page.
-- All polypropylene, bleach cleanable and covered by the Stainfree for
-- Life Guarantee. Room photos are in public/ranges/abingdon/, and a
-- swatch photo for every shade is in public/ranges/abingdon/<range>/.
-- Each links to the range on Abingdon's site, where samples are ordered.
-- No prices yet (Abingdon does not publish them): NULL shows "£ — price
-- coming soon" and keeps them out of the estimator until the shop adds one.
INSERT INTO ranges
  (id, name, material, spec, price, grade, rooms, widths, pile, colours,
   photo_url, sort_order, showcase, description,
   brand, category, features, colour_names, colour_photos, sample_url, price_from)
