  ('country-life', 'Country Life', 'Carpet', 'Polypropylene saxony · 14mm pile', NULL, 'Heavy domestic / general commercial', ARRAY['Living', 'Bedroom', 'Stairs', 'Hall']::text[], ARRAY[4, 5]::double precision[], 'saxony', ARRAY['#9B8E80', '#746B60']::text[], '/ranges/abingdon/country-life.jpg', 2, NULL, 'A deep 14mm saxony in soft, natural country tones. It feels luxurious underfoot but is tough enough for busy rooms, with a soft fleece back.', 'Abingdon', 'Stainfree', ARRAY['Stain resistant', 'Bleach cleanable', 'Stainfree for Life Guarantee', 'Deep pile', '10 Year Wear Warranty', 'Made in Britain']::text[], ARRAY['Witch Hazel', 'Walnut', 'Soft Silver', 'Pastoral', 'Limestone', 'Hopsack', 'Hessian', 'Greystone', 'Granite', 'Dapple Mare', 'Cocoa', 'Chestnut', 'Barn Owl', 'Ash Grove']::text[], ARRAY['/ranges/abingdon/country-life/witch-hazel.jpg', '/ranges/abingdon/country-life/walnut.jpg', '/ranges/abingdon/country-life/soft-silver.jpg', '/ranges/abingdon/country-life/pastoral.jpg', '/ranges/abingdon/country-life/limestone.jpg', '/ranges/abingdon/country-life/hopsack.jpg', '/ranges/abingdon/country-life/hessian.jpg', '/ranges/abingdon/country-life/greystone.jpg', '/ranges/abingdon/country-life/granite.jpg', '/ranges/abingdon/country-life/dapple-mare.jpg', '/ranges/abingdon/country-life/cocoa.jpg', '/ranges/abingdon/country-life/chestnut.jpg', '/ranges/abingdon/country-life/barn-owl.jpg', '/ranges/abingdon/country-life/ash-grove.jpg']::text[], 'https://www.abingdonflooring.co.uk/range/country-life/', true),
  ('country-linear', 'Country Linear', 'Carpet', 'Polypropylene loop · linear design', NULL, 'Heavy domestic / general commercial', ARRAY['Living', 'Bedroom', 'Stairs', 'Hall']::text[], ARRAY[4, 5]::double precision[], 'loop', ARRAY['#989184', '#726D63']::text[], '/ranges/abingdon/country-linear.jpg', 2, NULL, 'The linear design from the Country Collection, with a sleek, contemporary look. Built to resist stains, fading and wear, with a fleece backing.', 'Abingdon', 'Stainfree', ARRAY['Stain resistant', 'Bleach cleanable', 'Stainfree for Life Guarantee', 'Fade resistant', '10 Year Wear Warranty', 'Made in Britain']::text[], ARRAY['Paloma', 'Mirage', 'Elephant', 'Biscotti', 'Berber', 'Ivory']::text[], ARRAY['/ranges/abingdon/country-linear/paloma.jpg', '/ranges/abingdon/country-linear/mirage.jpg', '/ranges/abingdon/country-linear/elephant.jpg', '/ranges/abingdon/country-linear/biscotti.jpg', '/ranges/abingdon/country-linear/berber.jpg', '/ranges/abingdon/country-linear/ivory.jpg']::text[], 'https://www.abingdonflooring.co.uk/range/country-linear/', true),
