-- Sheet vinyl from Furlong Flooring: Furlong's own ranges and the Tarkett
-- ranges it distributes. Photos and a swatch per design are in
-- public/ranges/furlong/. Furlong publishes widths only for its own
-- ranges (2m, 3m, 4m); the Tarkett ones assume the same. No prices yet:
-- NULL shows "£ — price coming soon" until the shop adds one.
INSERT INTO ranges
  (id, name, material, spec, price, grade, rooms, widths, pile, colours,
   photo_url, sort_order, showcase, description,
